import { test, expect } from '@playwright/test';

test.describe('Registration Form Email Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/register');
  });

  test('should display error message when submitting registration form with invalid email', async ({ page }) => {
    // Fill in valid name and password
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('John Doe');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('ValidPassword123');

    // Fill in invalid email
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('invalid-email-format');

    // Click submit button
    const submitButton = page.getByRole('button', { name: /register/i });
    await submitButton.click();

    // Wait for error message to appear
    await page.waitForTimeout(500);

    // Verify error message is displayed
    const errorMessage = page.getByText('Please enter a valid email address');
    await expect(errorMessage).toBeVisible();

    // Verify form is not submitted
    const successMessage = page.getByText('Registration successful');
    await expect(successMessage).not.toBeVisible();

    // Verify email input still contains invalid value
    await expect(emailInput).toHaveValue('invalid-email-format');
  });

  test('should allow form submission with valid email and display success message', async ({ page }) => {
    // Fill in valid name, email, and password
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('Jane Smith');

    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('jane.smith@example.com');

    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('ValidPassword123');

    // Click submit button
    const submitButton = page.getByRole('button', { name: /register/i });
    await submitButton.click();

    // Wait for success message
    await page.waitForTimeout(500);

    // Verify success message is displayed
    const successMessage = page.getByText('Registration successful');
    await expect(successMessage).toBeVisible();

    // Verify error message is not displayed
    const errorMessage = page.getByText('Please enter a valid email address');
    await expect(errorMessage).not.toBeVisible();

    // Verify user is redirected to dashboard
    await expect(page).toHaveURL(/.*\/dashboard/);
  });
});
